def clean(x):
 if isinstance(x,float) and not math.isfinite(x):return {'__nonfinite_float__':'nan' if math.isnan(x) else 'positive_infinity' if x>0 else 'negative_infinity'}
 if isinstance(x,dict):return {k:clean(v) for k,v in x.items()}
 if isinstance(x,list):return [clean(v) for v in x]
 return x
def canonical(x):return json.dumps(clean(x),sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()
def digest(x):return hashlib.sha256(canonical(x)).hexdigest()
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def write(path,x):
 with path.open('x') as f:json.dump(x,f,sort_keys=True,indent=2,allow_nan=False);f.write('\n')
def pair(ordinary,adversarial):return [ordinary,adversarial]
def case(inputs,expected,required,forbidden):return {'input_fixture':inputs,'expected_output':expected,'required_effects':required,'forbidden_effects':forbidden}

