def bind_cases(item,family):
 for index,c in enumerate(item['cases']):
  c.update(case_id=family+':case-'+str(index),pair_role='ordinary' if index==0 else 'adversarial_or_exception',source_family=family,scientific_split=None,source_output_generation='not_run')
  c['oracle']={'type':'independent post-execution artifact bytes plus handler/event journal','exact_output':c.pop('expected_output'),'required_effects':c.pop('required_effects'),'forbidden_effects':c.pop('forbidden_effects'),'model_self_report_sufficient':False,'implementation_qualification':'not_run','hidden_from_generation':['oracle','private_fixture_file contents','expected effect/utility outcomes']}
 return item

